window.ORIGEN_GUIDE_LOCALES.en={
"alerce-costero":{
"summary":"Ancient temperate rainforest, millennia-old alerce trees and high endemism in Chile’s Coastal Range between Corral and La Unión.",
"story":["Alerce Costero National Park was created in 2010 by combining former protected areas, public land and a donation from the Valdivian Coastal Reserve. Its 13,975 hectares protect exceptionally old temperate rainforests in the Coastal Range, between the communes of Corral and La Unión.","The main protagonist is the alerce, an extremely slow-growing tree. The so-called Millennial Alerce is the park’s best-known attraction and, according to CONAF information based on recent studies, is believed to be over 5,000 years old. The park is also notable for its high endemism: CONAF states that around 60% of its plant species are endemic."],
"highlights":[["Millennial Alerce","The park’s emblematic tree; visits have limited capacity and require a reserved time slot."],["Incendios del Pasado Trail","An interpretive route that helps explain the ecological history of the forest."],["Hermanos Milenarios","A trail in the Catrilelfu sector among giant trees and humid forest."],["Tepual forests and wetlands","Very humid environments filled with mosses, ferns and swamp forest."]],
"facts":[["Established","2010"],["Area","13,975 ha"],["Emblematic alerce","Over 5,000 years old according to studies cited by CONAF"],["Plant endemism","Approx. 60% according to CONAF"],["Millennial Alerce","Reservation required and limited capacity"],["Access sectors","Mirador, Chaihuín, Catrilelfu and Romaza"]],
"planning":{"bestSeason":"The park can be visited year-round, but rain, mud and road conditions may affect access. Spring and summer usually make the experience easier.","access":"Main access is from La Unión or Corral via secondary roads leading to the different park sectors.","transport":"Road conditions may make a 4×4 vehicle advisable. Always check CONAF’s current recommendation before traveling.","difficulty":"Moderate. Trails are not extremely long, but humidity, mud and elevation changes can increase the effort required.","services":"Trails and restrooms are available in enabled sectors, with accessibility infrastructure at specific points."},
"tips":["Reserve your Millennial Alerce time slot through Pases Parques before traveling.","Check access conditions: road conditions can change quickly after rain.","Bring waterproof clothing and footwear with good grip.","Drones, pets and fires are not allowed.","Do not touch or remove vegetation: the park’s value lies in its fragility and extremely slow growth."],
"idealFor":["Native forest","Botany","Photography","Hiking","Conservation"],"sourceLabels":["CONAF"]},
"base-torres":{
"summary":"Patagonia’s iconic full-day hike through the Ascencio Valley, lenga forest and a final rocky moraine to the granite towers.",
"story":["Base Torres is the best-known hike in Torres del Paine National Park and one of the images that most strongly represents Chilean Patagonia. The route climbs through the Ascencio Valley, crosses lenga forest and finishes with a demanding ascent over a moraine of large rocks.","The final reward is a turquoise glacial lagoon beneath the three granite spires of the Paine massif. The experience can change dramatically with the weather: sunshine, wind, rain or snow may all occur in the same day. More than a photo hike, this is a mountain route that requires planning and respect for park conditions."],
"highlights":[["Ascencio Valley","The first major section of the hike, with mountain views and strong weather changes."],["Lenga forest","A more sheltered section before the route’s most demanding part."],["Final moraine","A rocky climb where the greatest physical and technical effort is concentrated."],["Base Torres viewpoint","A glacial lagoon with a direct view of the three granite towers."]],
"facts":[["Official estimated time","Approx. 8 h round trip (2026 reference)"],["Difficulty","Moderate/high"],["Park","Torres del Paine"],["Environment","Valley, forest and glacial moraine"],["Duration","Full day"],["Trail status","Must be checked on the day"]],
"planning":{"bestSeason":"Spring and summer provide more daylight, but Patagonian weather is variable year-round. Special safety requirements may apply during the colder season.","access":"The hike begins in the Las Torres sector. The park is usually reached from Puerto Natales by car, bus or transfer.","transport":"Bus or transfer to the park with a connection to Las Torres, or private vehicle depending on your itinerary.","difficulty":"Moderate/high. The final moraine climb is demanding and the complete route requires good physical condition.","services":"Services and refuges are available near access areas, but during the hike you should be self-sufficient with water, food and warm clothing."},
"tips":["Check the park’s daily report and the latest entry time before starting.","Start early and avoid relying on the final available departure window.","Bring windproof and waterproof layers even if the morning is clear.","Wear hiking footwear and use poles if comfortable; additional equipment may be required in snow.","Do not feed wildlife or leave the marked trail."],
"idealFor":["Trekking","Patagonia","Photography","Mountains","Adventure"],"sourceLabels":["Chile Travel","Torres del Paine Park · Recommendations","CONAF"]},
"carretera-austral":{
"summary":"A 1,200+ km Patagonian road trip linking forests, glaciers, rivers, fjords and small communities from Puerto Montt to Villa O’Higgins.",
"story":["The Carretera Austral—Route 7—was conceived as a connectivity project to integrate isolated territories of Chilean Patagonia. The Ministry of Public Works places the development of the present route in the second half of the 1970s, building on studies carried out in the late 1960s. Its opening changed the relationship between communities that had previously depended heavily on sea, lake or air routes.","Today the road links Puerto Montt and Villa O’Higgins over more than 1,200 km, combining paved sections, gravel and ferry crossings. In 2024 the Ministry of Public Works officially designated it a Scenic Route, recognizing its cultural, environmental and tourism value in addition to its landscapes. Driving it means traveling through an inhabited Patagonia: towns, national parks, hot springs, farms, glaciers and small services appear as the road moves south."],
"highlights":[["Pumalín National Park","Temperate rainforest, trails, waterfalls and volcanoes at the northern gateway to Patagonia."],["Queulat National Park","The Hanging Glacier is one of the route’s major natural icons."],["General Carrera Lake","Turquoise waters and access to the Marble Caves from Puerto Río Tranquilo."],["Cerro Castillo","One of Aysén’s most recognizable mountain landscapes, with trekking and viewpoints."],["Tortel and Villa O’Higgins","Cypress boardwalks, fjords and the final stretch of Route 7 toward the Southern Patagonian Ice Field."]],
"facts":[["Length","More than 1,200 km"],["Start / end","Puerto Montt → Villa O’Higgins"],["Road type","Pavement, gravel and ferry crossings"],["Recognition","Official Scenic Route since 2024"],["Regions","Los Lagos and Aysén"],["Suggested time","7–14 days for a relaxed journey"]],
"planning":{"bestSeason":"December to March offers longer days and generally more favorable conditions. Outside summer the route can be quieter, but weather and reduced services require more planning.","access":"You can begin in Puerto Montt, served by El Tepual Airport, or enter the central section from Balmaceda/Coyhaique. The route continues by road and several ferry crossings.","transport":"A private or rental vehicle offers the greatest independence. A vehicle with good ground clearance is useful on remote sections; buses and operators also exist but are less frequent.","difficulty":"Moderate/high logistically. Distances, weather, ferries and limited services require careful planning.","services":"Accommodation, fuel, food and supplies are available in main towns, but long gaps between services are possible."},
"tips":["Book ferries and accommodation in advance during high season.","Do not rely on mobile coverage: download maps and reservations before setting out.","Check fuel and driving range before entering long remote sections.","Bring waterproof clothing and warm layers even in summer.","Leave flexibility in your itinerary because weather and ferry crossings can change travel times."],
"idealFor":["Road trip","Photography","Nature","Trekking","Patagonia"],"sourceLabels":["Chile Travel","Ministry of Public Works · Scenic Route"]},
"chiloe":{
"summary":"An island world of stilt houses, wooden churches, evergreen forest, seafood, myths and a strong living cultural identity.",
"story":["Chiloé’s identity was shaped by centuries of island life, navigation, agriculture, fishing and oral tradition. The territory preserves a strong Huilliche heritage and a material culture deeply connected to wood. That relationship with the environment can be seen in the palafitos, boats, wooden shingles and a cuisine shaped by both sea and land products.","One of its most recognized heritage ensembles is the Churches of Chiloé: 16 wooden temples inscribed as a UNESCO World Heritage Site. These buildings embody the encounter between Jesuit evangelization and the knowledge of local shipwrights. Myths such as the Caleuche, Pincoya and Trauco also remain part of the archipelago’s cultural memory."],
"highlights":[["Castro and its palafitos","Chiloé’s best-known image: houses on stilts shaped by the rhythm of the tides."],["Heritage churches","Sixteen wooden churches form the UNESCO-listed ensemble."],["Dalcahue and crafts","Markets, textiles, woodworking and connections to smaller islands."],["Chiloé National Park","Evergreen forest, tepual wetlands, dunes and Pacific coastline."],["Chilote cuisine","Curanto, milcaos, chapaleles, native potatoes and seafood."]],
"facts":[["UNESCO heritage","16 wooden churches"],["Air gateway","Mocopulli Airport"],["Road access","Pargua–Chacao ferry"],["Suggested time","3–5 days"],["Climate","Humid and highly variable"],["Season","Year-round destination"]],
"planning":{"bestSeason":"Year-round. Summer offers more daylight; autumn and winter feel more intimate but bring more rain. Waterproof clothing is useful in every season.","access":"Fly to Mocopulli near Castro, or travel via Puerto Montt and cross the Chacao Channel by ferry from Pargua.","transport":"A vehicle is useful for exploring several towns and parks. Local buses connect cities and some smaller communities.","difficulty":"Low in towns and cities; moderate on trails and natural areas because of mud, rain and changing weather.","services":"Castro, Ancud and Quellón have the widest range of accommodation, food, fuel and shops."},
"tips":["Do not make the itinerary too tight: distances are short, but weather can slow travel.","Bring waterproof clothing and footwear that can handle mud and rain.","Try local food beyond curanto: native potatoes, cheeses, shellfish and home-style dishes.","Check tickets and restrictions before visiting parks and reserves.","Make time for smaller towns; much of the Chilote experience lies beyond the most photographed routes."],
"idealFor":["Culture","Food","Families","Photography","Heritage","Nature"],"sourceLabels":["Chile Travel · Chiloé","Chile Travel · Churches"]},
"conguillio":{
"summary":"Araucaria forests, volcanic lava fields, lakes and lagoons beneath Llaima Volcano in one of La Araucanía’s defining landscapes.",
"story":["Conguillío was created in 1950 and today protects 60,832 hectares in La Araucanía. It is part of UNESCO’s Araucarias Biosphere Reserve and one of the best places in Chile to understand how volcanic activity and Andean forest continually reshape one another.","Llaima Volcano dominates the landscape, and its eruptions have left extensive lava fields that contrast with forests of araucaria, coigüe and other native species. Lakes and lagoons such as Conguillío, Captrén and Arcoíris complete a territory where, within only a few kilometers, you can move from ancient forest to an almost bare volcanic landscape."],
"highlights":[["Sierra Nevada Trail","One of the park’s most famous hikes, known for views over Conguillío Lake and Llaima."],["Arcoíris Lagoon","Submerged forest, intensely colored water and a short, photogenic walk."],["Truful Truful","River, waterfalls and geological traces linked to the volcanic landscape."],["Araucaria forests","The great symbol of the park and the mountains of La Araucanía."],["Conguillío Lake","A place for contemplation and seasonal activities when officially enabled."]],
"facts":[["Established","May 26, 1950"],["Area","60,832 ha"],["UNESCO Biosphere","Araucarias Biosphere Reserve"],["Main volcano","Llaima"],["Access points","Melipeuco, Curacautín and Cherquenco"],["Suggested time","1–2 days"]],
"planning":{"bestSeason":"Summer and early autumn generally provide easier access. In winter, snow completely changes the experience and may require 4×4 vehicles, chains or involve partial closures.","access":"From Temuco you can enter via Melipeuco in the south or Curacautín in the north. A western access through Cherquenco also exists.","transport":"A private vehicle or transfer makes the visit much easier. Most internal roads are gravel.","difficulty":"Variable: there are short trails as well as demanding hikes such as Sierra Nevada. Snow can significantly increase difficulty.","services":"During summer CONAF reports food services, cabins, camping, picnic areas and some lake activities, all subject to conditions."},
"tips":["Check park status the same day or the day before: access and trails may change because of snow, rain or volcanic conditions.","Buy or reserve admission through Pases Parques when required.","Wear hiking footwear; even short trails can include mud or loose volcanic rock.","Pets and fires are not allowed.","If hiking Sierra Nevada, confirm whether a guide is required or any restrictions are in force."],
"idealFor":["Trekking","Volcanoes","Forests","Photography","Families","Seasonal kayaking"],"sourceLabels":["CONAF","Chile Travel"]},
"futaleufu":{
"summary":"Turquoise rivers, world-class whitewater and Patagonian mountain landscapes in a small town built around outdoor adventure.",
"story":["Futaleufú means “Big River” in Mapudungun, and much of life in the territory revolves around its water. The Futaleufú River crosses a landscape of forests, mountains and rock walls, creating powerful rapids that have made the town an international reference for rafting and whitewater kayaking.","The destination, however, extends far beyond the river. Trails such as Piedra del Águila overlook the Espolón River valley and surrounding mountains; Lake Lonconao and Laguna Espejo offer a quieter experience, while rural roads, bridges and forests reveal a less crowded Patagonia closely tied to local life."],
"highlights":[["Rafting on the Futaleufú","The signature experience, with different river sections and operators for different skill levels."],["Piedra del Águila","A mountain viewpoint with panoramas over the valley and nearby peaks."],["Lake Lonconao","A peaceful setting for contemplation and low-intensity activities."],["Laguna Espejo","A nearby option for walking and enjoying the Patagonian landscape."]],
"facts":[["Name meaning","“Big River” in Mapudungun"],["Signature activity","Rafting and kayaking"],["From Chaitén","Approx. 150 km"],["From Coyhaique","Approx. 422 km"],["Suggested time","2–4 days"],["Climate","Patagonian and changeable"]],
"planning":{"bestSeason":"Spring and summer concentrate much of the river activity. Outside the main season, confirm operator availability and road conditions.","access":"From Puerto Montt you can follow the Bimodal Route and continue from Chaitén. It is also possible to arrive from Coyhaique by traveling north along the Carretera Austral.","transport":"Private vehicle, long-distance buses or transfers. Use specialized operators for river activities.","difficulty":"Variable. Viewpoints and hikes can be moderate; rafting and kayaking depend on river levels and require specialized guides and equipment.","services":"The town has accommodation, restaurants, adventure operators, shops and basic services."},
"tips":["Book river activities with formal operators and proper equipment.","Weather changes quickly: bring waterproof clothing even with a good forecast.","Reserve rafting and accommodation during high season.","Do not underestimate driving times from Puerto Montt or Coyhaique.","Combine a river day with trails or lagoons to understand the territory more fully."],
"idealFor":["Rafting","Kayaking","Trekking","Patagonia","Adventure","Photography"],"sourceLabels":["Chile Travel"]},
"general-carrera":{
"summary":"A vast turquoise Patagonian lake and the gateway to the celebrated marble formations of Puerto Río Tranquilo.",
"story":["General Carrera Lake is one of the defining landmarks of Chilean Patagonia and the Carretera Austral. Its glacial waters stretch between mountains and valleys whose appearance changes constantly with wind, light and season.","On its western shore near Puerto Río Tranquilo, water erosion has spent millennia shaping cavities and arches in marble outcrops. The Marble Cathedral, Chapel and Cave are reached by boat and have become some of Aysén’s most recognizable landscapes."],
"highlights":[["Marble Caves","Marble formations sculpted by water, reached by boat from Puerto Río Tranquilo."],["Puerto Río Tranquilo","The main base for tours, accommodation and connections to other attractions in the area."],["Carretera Austral","The drive to the lake is a central part of the experience and crosses some of Aysén’s most iconic scenery."],["Kayaking and boat tours","Two ways to approach the formations, always subject to wind and lake conditions."]],
"facts":[["Lake area","Approx. 1,850 km²"],["Visitor base","Puerto Río Tranquilo"],["From Coyhaique","Approx. 240 km"],["Driving time","Around 5 hours"],["Access to the Marble Caves","Boat or kayak"],["Suggested time","2 days"]],
"planning":{"bestSeason":"Spring and summer usually offer better connectivity and more services. Patagonian weather remains variable in every month.","access":"From Coyhaique travel south along the Carretera Austral to Puerto Río Tranquilo. The route combines paved and gravel sections.","transport":"Private vehicles and buses reach Puerto Río Tranquilo. Visits to the formations are made with boat or kayak operators.","difficulty":"Low for the conventional visit, but the lake can develop wind and waves. Safety depends on the day’s conditions and the operator.","services":"Puerto Río Tranquilo has accommodation, restaurants, limited fuel and tour operators. Book ahead during high season."},
"tips":["Book your boat trip in advance and confirm lake conditions the same day.","Keep your schedule flexible: wind can delay or cancel departures.","If driving from Coyhaique, do not estimate the journey from distance alone; gravel and stops extend travel time.","Bring waterproof warm clothing even in summer.","Use Puerto Río Tranquilo as a base to combine the visit with other parts of the Carretera Austral."],
"idealFor":["Patagonia","Boating","Kayaking","Photography","Road trip","Nature"],"sourceLabels":["Chile Travel — General Carrera Lake and Marble Caves"]},
"laguna-laja":{
"summary":"Mountains, snow, volcanism and trails beneath Antuco Volcano and Sierra Velluda in one of Biobío’s great Andean landscapes.",
"story":["Laguna del Laja National Park was created in 1958 and protects a landscape shaped by volcanism, glaciation and mountain ecosystems. Its image is dominated by Antuco Volcano, Sierra Velluda and the large Laguna del Laja.","Beyond its scenic value, the park protects mountain cypress formations, Andean wildlife and environments that change dramatically between summer and winter. It is one of Chile’s national parks where snow plays an especially important role in the visitor experience."],
"highlights":[["Antuco Volcano","The volcanic cone that dominates the landscape and defines much of the park’s visual identity."],["Sierra Velluda","A high mountain massif with glaciers, ravines and more demanding trekking routes."],["Laguna del Laja","A large mountain lake beside the road toward the Pichachén border pass."],["Short trails","Los Pangues, Las Chilcas–Torbellino and Los Coigües offer shorter outings."],["Winter","Snow transforms the park and draws visitors, but requires more preparation for driving and mountain conditions."]],
"facts":[["Established","June 25, 1958"],["Area","11,600 ha"],["Antuco Volcano","2,985 m a.s.l."],["Sierra Velluda","3,585 m a.s.l."],["Commune","Antuco"],["Suggested time","1 day"]],
"planning":{"bestSeason":"Year-round, with very different experiences. Summer favors hiking and driving; winter brings snow but may require chains, 4×4 and greater safety margins.","access":"Access is from Los Ángeles toward Antuco and Abanico. The final stretch includes gravel road, and winter conditions can change because of snow.","transport":"A private vehicle makes visiting easier. Public transport reaches Abanico, before the park entrance, so the final section must be arranged separately.","difficulty":"Variable: there are easy trails and longer routes such as Sierra Velluda, where exposure, elevation gain and mountain hazards increase.","services":"The park has viewpoints, environmental information, fishing and camping areas. Actual availability should be confirmed before traveling."},
"tips":["In winter carry chains and check road conditions before leaving Los Ángeles.","For longer trails, start early and expect rapid weather changes in the mountains.","Do not enter snowy mountain routes without suitable equipment and experience.","Check Pases Parques and CONAF notices on the day of your visit.","Respect closures, signage and ranger instructions."],
"idealFor":["Mountains","Trekking","Snow","Photography","Nature","Road trip"],"sourceLabels":["CONAF — Laguna del Laja National Park"]},
"nahuelbuta":{
"summary":"Ancient coastal araucaria forest, mountain trails and broad viewpoints across the Coastal Range between Biobío and La Araucanía.",
"story":["Created on January 4, 1939, Nahuelbuta protects 6,831.9 hectares of the Coastal Range. CONAF describes it as a natural relic preserving environments that have remained practically unchanged for thousands of years, giving the park exceptional ecological value.","Its landscape is unusual because araucaria trees grow far from their better-known Andean distribution. The main viewpoint is Piedra del Águila, at around 1,460 meters above sea level: on clear days it offers a broad view of the territory between the Pacific and the Andes. The park also protects species of high conservation interest such as Darwin’s fox, along with notable amphibian and bird diversity."],
"highlights":[["Piedra del Águila","The park’s emblematic viewpoint, with views toward the coast and the Andes."],["Casa de Piedra Trail","A shorter, more accessible option for a half-day visit."],["Cerro Anay","A short trail that complements the main routes."],["Araucaria forests","A coastal population of araucarias with major biogeographic value."]],
"facts":[["Established","January 4, 1939"],["Area","6,831.9 ha"],["Piedra del Águila","Approx. 1,460 m a.s.l."],["Main trail","Piedra del Águila · 6.4 km"],["Access","Angol, Cañete and secondary roads"],["Services inside park","Very limited / check before visiting"]],
"planning":{"bestSeason":"Spring through autumn generally offers better conditions. In winter and after heavy rain, access roads and trails can become difficult.","access":"The main access is from Angol via Vegas Blancas. Other routes enter from Cañete and secondary roads to the north.","transport":"A private vehicle is recommended; final road sections can be slow and conditions vary.","difficulty":"Moderate. Main trails include elevation gain and some routes take several hours.","services":"CONAF warns that services inside the park are very limited, so arrive self-sufficient."},
"tips":["Carry enough water and food for the full day.","Use layered clothing, waterproof gear and hiking shoes.","Check opening hours and road conditions with CONAF before leaving.","Pets and fires are not allowed; take all rubbish with you.","On forest trails watch for branches, mud and rapid weather changes."],
"idealFor":["Araucarias","Trekking","Viewpoints","Photography","Nature"],"sourceLabels":["CONAF"]},
"nevados-chillan":{
"summary":"An active volcanic mountain destination combining winter snow, thermal waters, skiing, snowboarding and summer bike and hiking experiences.",
"story":["Nevados de Chillán is built around an active volcanic complex in the Ñuble Andes. The mountain has shaped both the landscape and tourism: snow in winter, volcanic hot springs and forests whose use changes with the seasons.","Chile Travel recognizes it as one of the continent’s major mountain resorts. Its ski area has more than 30 runs and includes Las Tres Marías, a 13 km descent through native forest. In summer, part of the infrastructure becomes a Bike Park, alongside trekking, horseback riding and other mountain experiences."],
"highlights":[["Skiing and snowboarding","The main winter experience, with slopes for different ability levels."],["Las Tres Marías","A 13 km run described by Chile Travel as the longest ski descent in South America."],["Hot springs","Thermal pools allow visitors to combine sport and relaxation."],["Bike Park and summer","During warmer months the mountain shifts toward cycling, trekking and other outdoor activities."]],
"facts":[["Runs","More than 30"],["Las Tres Marías","13 km"],["From Chillán","Approx. 80 km via Route N-55"],["From Concepción","Approx. 190 km total"],["Suggested time","2–3 days"],["Season","Year-round mountain destination"]],
"planning":{"bestSeason":"Winter for snow; summer for cycling and trekking. Hot springs complement the experience through much of the year.","access":"From Chillán, climb Route N-55 toward Valle de Las Trancas and Nevados. From Concepción, the trip combines Route 5 and N-55.","transport":"Car, transfer or seasonal buses from Chillán. In winter check chain requirements and road status.","difficulty":"Low to high depending on activity. Skiing, snowboarding and the bike park require technical ability appropriate to the chosen run.","services":"A broad range of accommodation, restaurants, equipment rental, lessons, spa and thermal facilities is available in the area."},
"tips":["Book accommodation and activities early during snow season.","Bring thermal and waterproof clothing, gloves, goggles and sunscreen.","Check road conditions and chain requirements before climbing in winter.","If skiing or snowboarding for the first time, take a lesson before entering demanding slopes.","In summer, confirm which lifts, trails and services are operating."],
"idealFor":["Snowboarding","Skiing","Hot springs","Bike park","Mountains","Families"],"sourceLabels":["Chile Travel · Nevados","Chile Travel · Hot Springs"]},
"pan-azucar":{
"summary":"Coastal desert, camanchaca fog, endemic cacti and marine wildlife where the Atacama meets the Pacific Ocean.",
"story":["Pan de Azúcar National Park was created on October 7, 1985 and protects 43,754 hectares across the Atacama and Antofagasta regions. Its landscape combines arid hills, ravines, rocky coastline and an island system formed by Pan de Azúcar Island, islets and exposed rocks.","Its defining feature is the influence of the camanchaca, coastal fog that brings moisture to an extremely dry environment. It supports communities of cacti and other desert-adapted plants. CONAF records more than 18 cactus species in the park, while wildlife ranges from guanacos and foxes on land to marine otters, sea lions, coastal birds and Humboldt penguins offshore."],
"highlights":[["Coastal desert viewpoints","Views where arid relief drops directly toward the ocean."],["Pan de Azúcar Island","Authorized boat trips allow visitors to observe the marine environment without landing."],["Desert cacti","Camanchaca supports highly specialized flora with strong endemism."],["Wildlife watching","Guanacos, seabirds, sea lions and, from a respectful distance, Humboldt penguins."]],
"facts":[["Established","October 7, 1985"],["Area","43,754 ha"],["Cacti","More than 18 recorded species"],["Access from Chañaral","Route C-120 · approx. 27 km"],["Public transport","Does not reach the park directly"],["Swimming","Beaches are not suitable for swimming according to CONAF"]],
"planning":{"bestSeason":"The park can be visited year-round. Mornings may bring camanchaca and solar radiation remains intense even under coastal cloud.","access":"The main access is Route C-120 from Chañaral. Secondary routes also connect from Route 5.","transport":"CONAF indicates access by private vehicle or tour operators; there is no direct public transport.","difficulty":"Low/moderate depending on the trail. Dry conditions, solar radiation and limited shade increase the effort required.","services":"Tourism services are operated by local providers. Check availability and entry requirements before visiting."},
"tips":["Carry enough water, a hat, sunscreen and clothing for wind.","Use binoculars to observe wildlife without approaching it.","Beaches have dangerous currents and should not be treated as swimming areas.","Stay on authorized trails and roads.","Check schedules and conditions with CONAF/Pases Parques before traveling."],
"idealFor":["Wildlife","Desert","Photography","Hiking","Coast","Nature"],"sourceLabels":["CONAF","Chile Travel"]},
"peninsula-hualpen":{
"summary":"A coastal mosaic of cliffs, wetlands, native forest and local heritage within Greater Concepción.",
"story":["The Hualpén Peninsula was declared a Nature Sanctuary in 1976 and protects one of the most diverse coastal landscapes in the Concepción metropolitan area. Within a relatively compact territory are wetlands, native forest, coastal scrub, lagoons, estuary, beaches and cliffs.","Its value is not only scenic. The sanctuary protects important habitats for birds and regional flora, along with places of historical and cultural interest. Its proximity to the city makes it an especially accessible gateway to the natural heritage of the Biobío Region."],
"highlights":[["Lenga Wetland","An estuarine wetland of high biodiversity value and an important birdwatching area."],["Cliffs and coastline","Natural viewpoints over the Pacific and a strongly contrasting coastal geography."],["Native forest","Fragments of coastal vegetation representing ecosystems increasingly scarce in the metropolitan environment."],["Pedro del Río Zañartu Park","A historic and scenic area linked to the mouth of the Biobío River and local memory."],["Beaches and fishing coves","Different sectors combine scenery, artisanal fishing and coastal experiences."]],
"facts":[["Category","Nature Sanctuary"],["Declared","1976"],["Official area","2,069 ha"],["Commune","Hualpén"],["Ecosystems","Wetlands, forest, coast and cliffs"],["Suggested time","Half day to 1 day"]],
"planning":{"bestSeason":"Year-round. Spring and summer favor walks and viewpoints; autumn and winter may bring rain, wind and wet trails.","access":"Access varies by sanctuary sector. Plan from Hualpén or Concepción and confirm road, gate and permitted-access conditions beforehand.","transport":"A private vehicle or public transport to nearby urban sectors helps with access, but some points require walking and not all internal roads are freely open.","difficulty":"Low to moderate depending on the sector. Risk increases on cliffs and informal trails in mud, strong wind or poor visibility.","services":"Services are concentrated in urban areas and places such as Lenga. Do not assume toilets, water or shops are available in interior natural areas."},
"tips":["Avoid unofficial paths near cliffs, especially during rain or strong wind.","Confirm that access to the sector you want to visit is permitted; parts of the peninsula include private property and roads with changing restrictions.","Carry out all waste and avoid sensitive wetland or nesting areas.","For photography and birdwatching, early hours usually have less human activity.","Combine nature with local heritage to better understand the sanctuary’s value."],
"idealFor":["Coast","Hiking","Photography","Birdwatching","Nature","Short escapes"],"sourceLabels":["Ministry of the Environment — Hualpén Peninsula"]},
"petrohue":{
"summary":"Volcanic waterfalls, temperate rainforest, lake and volcanoes inside Chile’s oldest national park.",
"story":["The Petrohué Falls are part of Vicente Pérez Rosales National Park, created in 1926. The territory combines volcanic, glacial and tectonic processes that shaped the lakes, rivers and mountains around Puerto Varas.","The Petrohué River runs over volcanic rock, forming powerful rapids and waterfalls of intense color. Nearby lies Todos los Santos Lake, making it possible to combine temperate forest, volcanoes, navigation and Andean viewpoints in a single day."],
"highlights":[["Petrohué Falls","Rapids and waterfalls over volcanic rock, with volcano views when weather allows."],["Todos los Santos Lake","A glacial lake surrounded by mountains and forest, connected with Petrohué and Peulla."],["Osorno Volcano","One of the park’s major visual landmarks and a symbol of the Llanquihue Lake circuit."],["Temperate rainforest","Trails and vegetation typical of the southern Andes accompany much of the route."]],
"facts":[["Park","Vicente Pérez Rosales"],["Established","August 17, 1926"],["Area","More than 253,000 ha"],["Main access","Route 225-CH"],["Recommended base","Puerto Varas or Ensenada"],["Suggested time","1 day"]],
"planning":{"bestSeason":"Year-round. Spring and summer bring more visitors and longer days; autumn and winter offer a different atmosphere with more rain and possible restrictions.","access":"From Puerto Varas take Route 225-CH toward Ensenada and Petrohué. It is one of the classic excursions around Lake Llanquihue.","transport":"Access is possible by private vehicle, tour or buses operating toward Ensenada and Petrohué. Confirm schedules before traveling.","difficulty":"Low at the main viewpoints and walks; other activities in the park may require more time and preparation.","services":"Ensenada and Puerto Varas have the widest range of services. Tourism services operate in Petrohué but may vary by season and conditions."},
"tips":["Buy or reserve admission according to CONAF and Pases Parques instructions.","Bring waterproof clothing even with a stable forecast: rain is a normal part of the local climate.","Do not approach unauthorized areas near the river; the current is powerful and rocks can be slippery.","If combining the falls with Todos los Santos Lake, organize schedules before leaving.","During high season start early to reduce congestion and find parking."],
"idealFor":["Nature","Families","Photography","Forests","Volcanoes","Road trip"],"sourceLabels":["CONAF — Vicente Pérez Rosales National Park"]},
"pichilemu":{
"summary":"Chile’s surf capital, combining the Pacific, Punta de Lobos, dramatic cliffs, coastal life and year-round board sports.",
"story":["Pichilemu has built much of its contemporary tourism identity around the ocean and board sports. A few kilometers south of the town center, Punta de Lobos concentrates that relationship between community, landscape and surfing: consistent waves, cliffs, rocky stacks and an open Pacific coast.","Punta de Lobos was recognized as a World Surfing Reserve, a designation intended to protect not only wave quality but also the natural and cultural environment around it. The area attracts experienced surfers, surf schools, photographers and travelers who simply want to watch the sunset over the ocean."],
"highlights":[["Punta de Lobos","Rocky stacks, major breaks and one of Chile’s most iconic coastal landscapes."],["Surfing and bodyboarding","Schools for beginners and internationally recognized conditions."],["Viewpoints and photography","The open coast and seabirds make the area an excellent observation point."],["Pichilemu town","Restaurants, cafés, shops and coastal life complement the beach experience."]],
"facts":[["Distance from Pichilemu","Approx. 6 km"],["From Santiago","Approx. 210 km"],["Recognition","World Surfing Reserve"],["Suggested time","1–3 days"],["Signature activity","Surfing"],["Demand","High in summer"]],
"planning":{"bestSeason":"Year-round. Summer draws the largest crowds; autumn and winter attract surfers and offer a quieter coast, with lower temperatures.","access":"From Santiago the drive takes just over three hours. Regular buses serve Pichilemu. Punta de Lobos is around 6 km from the town center.","transport":"Shared taxi, taxi, bicycle or private vehicle can connect Pichilemu with Punta de Lobos.","difficulty":"Low for viewpoints and coastal visits. Water activities require experience, lessons or an assessment of sea conditions.","services":"Pichilemu has a broad range of accommodation, restaurants, surf schools and equipment rental."},
"tips":["If surfing, check sea conditions and choose a school or operator suited to your level.","Wind and temperature drop around sunset, so bring an extra layer.","Book accommodation in advance during summer.","Respect access routes, conservation areas and coastal signage.","Even if you do not surf, Punta de Lobos is worth visiting for scenery and photography."],
"idealFor":["Surfing","Short escapes","Photography","Coast","Couples","Adventure"],"sourceLabels":["Chile Travel · Punta de Lobos"]},
"rapa-nui":{
"summary":"A volcanic Polynesian island where landscape, archaeology and living culture come together around the Rapa Nui legacy.",
"story":["Rapa Nui is one of the most isolated inhabited territories on the planet and preserves a unique Polynesian identity within Chile. Its cultural landscape is marked by volcanoes, ancient roads, ceremonial villages, quarries and stone platforms associated with the moai.","Visiting the island involves far more than archaeological sites: the experience combines heritage, coast, volcanoes, food, local stories and a contemporary culture that maintains deep ties with the territory."],
"highlights":[["Rano Raraku","The volcanic quarry where most moai were carved and one of the island’s most important archaeological sites."],["Ahu Tongariki","A major ceremonial platform with fifteen moai facing the ocean."],["Rano Kau and Orongo","A volcanic crater and ceremonial village linked to the former tangata manu, or birdman, cult."],["Anakena","A light-sand beach with strong cultural importance and ceremonial platforms."],["Hanga Roa","The main town and base for accommodation, food, services and island tours."]],
"facts":[["Access","Direct flight from Santiago to Mataveri (IPC)"],["Flight time","Approx. 5 h 30 min"],["Maximum tourist stay","30 days"],["Suggested time","4 days or more"],["Heritage","Rapa Nui National Park"],["Important","Several sites require an accredited local guide"]],
"planning":{"bestSeason":"The island can be visited year-round. The climate is subtropical and variable; January to March brings warmer conditions and the Tapati period.","access":"Regular access is by air from Santiago to Mataveri International Airport. Review the island’s special entry requirements before traveling.","transport":"From Hanga Roa you can travel by tour, rental vehicle or bicycle. Several major archaeological sites require an accredited local guide.","difficulty":"Low to moderate on conventional visits; higher on hikes, caves and volcanic terrain with uneven ground.","services":"Hanga Roa has accommodation, restaurants, vehicle rental, operators and basic services. Supply is more limited than on the mainland, so reservations are recommended."},
"tips":["Complete the Single Entry Form within the required period before your flight and review all current entry requirements.","Buy the National Park ticket and arrange guided visits in advance for sites that require an accredited guide.","Do not touch, climb on or cross restricted areas around moai, ahu or other archaeological remains.","Bring sunscreen, a light waterproof layer and sturdy footwear; weather can change quickly.","Leave room in the itinerary to talk with people, eat and explore Hanga Roa: living culture is a central part of the journey."],
"idealFor":["Culture","Archaeology","Islands","Photography","Nature","Heritage"],"sourceLabels":["Chile Travel — Rapa Nui","Chile Travel — Entry requirements"]},
"ruta-lagos-volcanes":{
"summary":"A vast network of road-trip circuits linking lakes, rivers, active volcanoes, national parks, hot springs and mountain towns across southern Chile.",
"story":["The Lakes and Volcanoes Route is not a single road, but a large tourism network connecting territories in La Araucanía, Los Ríos and Los Lagos. Its value lies in linking Andean and lake landscapes with cities, towns, communities, cuisine and local traditions, allowing anything from short trips to journeys lasting several weeks.","Chile Travel organizes it into six circuits and counts 26 major rivers, 22 lakes, 17 active volcanoes and 12 national parks. Add mountain resorts and a strong concentration of hot springs, and the route changes completely with the season: snow and thermal waters in winter; boating, trekking, cycling and parks during warmer months."],
"highlights":[["Araucanía Lacustre","Pucón, Villarrica, lakes, hot springs and access to volcanoes and national parks."],["Araucanía Andina","Lonquimay, Malalcahuello, Conguillío and landscapes of araucarias and mountains."],["Seven Lakes Circuit","A route through water and forest linking towns and lakes in Los Ríos Region."],["Lake Llanquihue","Puerto Varas, Frutillar and views of Osorno and Calbuco volcanoes."],["Hot springs and snow","The region concentrates winter resorts and numerous thermal alternatives."]],
"facts":[["Length","More than 2,000 km"],["Circuits","6 tourism circuits"],["Lakes","22 major lakes"],["Active volcanoes","17"],["National parks","12"],["Rivers","26 major rivers"]],
"planning":{"bestSeason":"Year-round. Summer favors road trips, parks and boating; autumn brings color; winter centers on snow and hot springs; spring combines snowmelt with lower demand.","access":"The main air gateways are Temuco and Puerto Montt. Route 5 is the longitudinal backbone, with roads branching toward the different circuits.","transport":"A car provides the greatest flexibility for combining several circuits. Buses connect main cities and operators serve specific excursions.","difficulty":"Low/moderate logistically. Some mountain roads change considerably with snow, rain or volcanic activity.","services":"Broad services are available in tourism centers such as Pucón, Valdivia, Puerto Varas and Osorno, with more limited supply in mountain areas."},
"tips":["Plan by circuit rather than trying to cover the entire route in a single trip.","In winter check chains, road status and mountain resort conditions.","Review official volcanic alerts before activities near active volcanic complexes.","Reserve popular hot springs and accommodation in advance.","Combine nature with food and local culture: the route’s value goes well beyond scenery."],
"idealFor":["Road trip","Lakes","Hot springs","Volcanoes","Families","Adventure"],"sourceLabels":["Chile Travel"]},
"san-pedro-atacama":{
"summary":"A historic desert oasis used as a base for exploring salt flats, volcanoes, high-altitude lagoons, geysers and some of the clearest skies on Earth.",
"story":["San Pedro de Atacama developed around an oasis in one of the driest environments on the planet. Its position between the Domeyko Range and the Andes made it a transit and exchange point for Atacameño communities and highland routes for centuries.","Today it is the main tourism base of the Atacama Desert. Excursions leave town for the Moon Valley, El Tatio Geysers, salt flats, high-altitude lagoons, hot springs and observatories, combining landscape, archaeology, local culture and astronomy."],
"highlights":[["Moon Valley","Salt formations, dunes and desert ridges only a few kilometers from town."],["El Tatio Geysers","A high-altitude geothermal field commonly visited at sunrise."],["Lagoons and salt flats","High-Andean landscapes combining volcanoes, salt, wildlife and vast horizons."],["Astrotourism","Dry air and low light pollution create exceptional conditions for observing the night sky."],["Atacameño culture","The destination is best understood by including archaeological heritage, salt-flat villages and local traditions."]],
"facts":[["Tourism base","San Pedro de Atacama"],["Main airport","El Loa, Calama (CJC)"],["Distance from Calama","Approx. 100 km"],["Suggested time","3–4 days"],["Landscape","Desert and Altiplano"],["Practical key","Acclimatize before high-altitude excursions"]],
"planning":{"bestSeason":"Year-round. Days are usually dry and sunny, while nights can be very cold; the day-night temperature contrast is stronger in winter.","access":"The most common route is to fly to Calama and continue approximately 100 km along Route 23 to San Pedro de Atacama.","transport":"The town is walkable, while most outlying attractions are visited by tour, transfer or private vehicle.","difficulty":"Variable. Excursions close to town are easy, but Altiplano trips can climb well above 4,000 meters in altitude.","services":"San Pedro concentrates accommodation, food, tour operators, vehicle rental and tourism services. Book ahead during high-demand periods."},
"tips":["On your first day, prioritize lower-altitude activities if arriving directly from sea level.","Bring sunscreen, water and warm layers even in warmer months.","Do not underestimate the cold on pre-dawn tours such as El Tatio.","Book tours and access with formal operators and confirm which entrance fees are included.","Respect archaeological sites, local communities and fragile salt-flat and highland environments."],
"idealFor":["Desert","Astronomy","Photography","Culture","Adventure","Road trip"],"sourceLabels":["Chile Travel — San Pedro de Atacama"]},
"siete-tazas":{
"summary":"Pools, waterfalls and pre-Andean forest along the Claro River in one of the Maule Region’s best-known natural landscapes.",
"story":["The Radal Siete Tazas area protects forests and waterways in the foothills of the Maule Region. Its defining image is a sequence of pools and waterfalls carved by the Claro River into volcanic rock, accompanied by viewpoints and trails of different lengths.","Beyond the classic circuit, the area offers routes into forest, mountain sectors and interior valleys. Conditions vary significantly by season, so the experience can range from a short family walk to longer routes requiring careful planning."],
"highlights":[["Siete Tazas","The sequence of pools and waterfalls that gives the destination its name."],["Salto de la Leona","One of the best-known waterfalls and part of the protected area’s short circuit."],["Forest trails","Routes such as El Coigüe and other options lead into native vegetation."],["Longer routes","Areas such as El Bolsón and Valle del Indio extend the experience when officially open."]],
"facts":[["Commune","Molina"],["CONAF unit area","1,009.34 ha"],["Siete Tazas–Leona circuit","Approx. 1.5 km"],["Short circuit duration","Approx. 1 hour"],["Access","From Molina toward Parque Inglés"],["Suggested time","1 day"]],
"planning":{"bestSeason":"Spring through early autumn is generally the easiest period for walking. Winter brings more mud, snow and the possibility of closures or restrictions.","access":"The main access is from Molina toward the Parque Inglés sector. A significant part of the final section is gravel.","transport":"A private vehicle makes access easier. If you are not driving, check local transport or tour options from Molina and Curicó in advance.","difficulty":"From easy on the main circuit to demanding on longer trails. Some extended routes may close seasonally or for safety reasons.","services":"CONAF reports trails, picnic areas, viewpoints, camping and other services in the unit, subject to operation and season."},
"tips":["Check CONAF and Pases Parques before leaving: some trails may be closed even when the main area is open.","Wear footwear with good grip; walkways, steps and rock can be wet or icy.","Do not enter the water in unauthorized areas and respect safety barriers.","Carry water and sun protection on longer circuits.","Avoid planning a long hike if arriving late; several routes require many hours."],
"idealFor":["Waterfalls","Hiking","Forests","Families","Photography","Nature"],"sourceLabels":["CONAF — Radal Siete Tazas"]},
"valle-elqui":{
"summary":"A valley of towns, vineyards, astronomy and semi-arid landscapes where the Andes meet pisco culture and Gabriela Mistral’s legacy.",
"story":["The Elqui Valley runs inland from La Serena toward the foothills along the Elqui River basin. The landscape combines arid slopes with intensely green agricultural areas, historic towns and a long tradition of grape growing and pisco production.","The destination is also one of Chile’s major astrotourism centers. Vicuña serves as a service hub and gateway to observatories, while Pisco Elqui, Montegrande, Cochiguaz and other towns make it possible to build a journey combining culture, food and deep night skies."],
"highlights":[["Vicuña","The valley’s main city, linked to Gabriela Mistral and a base for services and astronomy."],["Pisco Elqui","An inland town surrounded by mountains, distilleries and tourism accommodation."],["Observatories","Atmospheric stability and clear skies have fostered a strong astronomy tourism offer."],["Pisco route","Distilleries and producers reveal a central part of the valley’s agricultural and culinary identity."],["Interior towns","Montegrande, Paihuano, Cochiguaz and other areas extend the trip beyond the main stops."]],
"facts":[["Region","Coquimbo"],["Gateway","La Serena"],["Main road","Route 41"],["Initial distance from La Serena","Approx. 33 km to the valley"],["Suggested time","2–3 days"],["Ideal for","Astronomy and road trips"]],
"planning":{"bestSeason":"Year-round. Days are usually sunny and nights can be cold even in summer, an important consideration for astronomy activities.","access":"From La Serena take Route 41 toward Vicuña and the valley’s interior towns.","transport":"Bus, rental car or tours can cover the main corridor. A vehicle provides much more freedom for observatories, distilleries and smaller towns.","difficulty":"Low for the general route. Some hikes and interior areas require more preparation.","services":"Vicuña, Paihuano and Pisco Elqui concentrate accommodation, food, shops and operators. During high season, book observatories and lodging ahead."},
"tips":["Book astronomy visits in advance and check the moon phase according to the experience you want.","Bring warm clothing for the night even after a hot day.","If driving and doing pisco tastings, arrange a designated driver or tour.","Do not focus everything on Pisco Elqui: Vicuña and intermediate towns provide much of the valley’s cultural context.","Spend at least one night inland to enjoy the sky without a late return to La Serena."],
"idealFor":["Astronomy","Food","Culture","Couples","Road trip","Photography"],"sourceLabels":["Chile Travel — Elqui Valley"]}
};